import sys,json,fnmatch
d=json.load(sys.stdin)
def match(subj,filt):
    f=filt.split('.'); s=subj.split('.')
    for i,t in enumerate(f):
        if t=='>': return i<=len(s)
        if i>=len(s): return False
        if t!='*' and t!=s[i]: return False
    return len(s)==len(f)
bad=[]
for a in d['account_details']:
    for st in a.get('stream_detail',[]):
        filts=st['config']['subjects']
        subs=list((st['state'].get('subjects') or {}).keys())
        print(st['name'], st['state']['messages'],'msgs', filts, '| distinct subjects:', len(subs))
        for s in subs:
            ok=any(match(s,f) for f in filts)
            print(('  OK   ' if ok else '  MISS '), s)
            if not ok: bad.append((st['name'],s))
print('UNMATCHED:', bad)
"

